// Little Hotelier: auth/HTTP adapter only. All business writes belong to ONE DB transaction.
import { createClient } from 'npm:@supabase/supabase-js@2';
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};
function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {status, headers: {...corsHeaders, 'Content-Type': 'application/json'}});
}
Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method === 'OPTIONS') return new Response('ok', {headers: corsHeaders});
  if (req.method !== 'POST') return json({error: 'Method not allowed'}, 405);
  const expectedKey = Deno.env.get('LH_SYNC_API_KEY');
  if (!expectedKey || req.headers.get('Authorization') !== `Bearer ${expectedKey}`) return json({error: 'Unauthorized'}, 401);
  let payload: Record<string, unknown>;
  try {
    const body = await req.json();
    if (!body || typeof body !== 'object' || Array.isArray(body)) return json({error: 'Invalid JSON body'}, 400);
    payload = body;
    if (['external_id','check_in','check_out'].some(k => typeof payload[k] !== 'string' || !(payload[k] as string).trim())) {
      return json({error: 'Missing required fields'}, 400);
    }
  } catch {
    return json({error: 'Invalid JSON body'}, 400);
  }
  const url = Deno.env.get('SUPABASE_URL');
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if (!url || !key) return json({error: 'Backend configuration missing'}, 503);
  try {
    const client = createClient(url, key, {auth: {persistSession: false, autoRefreshToken: false}});
    const {data, error} = await client.rpc('lh_apply_reservation_atomic', {p_payload: payload});
    if (error) {
      // Do not echo SQL messages, payloads or guest data. Do not retry an ambiguous call here.
      console.error('LH atomic RPC failed', typeof error.code === 'string' ? error.code : 'unknown');
      return json({error: 'Synchronization failed; reconcile before retry', code: 'lh_atomic_rpc_failed'}, 500);
    }
    if (!data || data.success !== true || data.external_id !== payload.external_id || !data.reservation_id ||
        !Array.isArray(data.warnings) || !Array.isArray(data.tasks_created) || !Array.isArray(data.tasks_cancelled)) {
      return json({error: 'Unexpected synchronization response; reconcile before retry', code: 'lh_invalid_rpc_result'}, 502);
    }
    return json(data);
  } catch {
    console.error('LH atomic RPC transport failed');
    return json({error: 'Synchronization outcome unknown; reconcile before retry', code: 'lh_outcome_unknown'}, 503);
  }
});
